<?php
namespace App\Services;use App\Models\{AttendanceEvent,AttendanceParticipant};use Illuminate\Validation\ValidationException;
class AttendanceAccessService{public function validateToken(AttendanceEvent $event,string $token):void{if(!$event->public_access_enabled||!hash_equals((string)$event->access_token_hash,hash('sha256',$token)))throw ValidationException::withMessages(['access'=>'El enlace de asistencia no es válido o fue reemplazado.']);if($event->access_token_expires_at&&now()->gte($event->access_token_expires_at))throw ValidationException::withMessages(['access'=>'El enlace de asistencia expiró.']);if(!$event->isOpen())throw ValidationException::withMessages(['access'=>'La asistencia no se encuentra abierta en este momento.']);}public function identify(AttendanceEvent $event,string $code):AttendanceParticipant{$participant=$event->participants()->where('credential_hash',hash('sha256',strtoupper(trim($code))))->first();if(!$participant||($participant->credential_expires_at&&now()->gte($participant->credential_expires_at)))throw ValidationException::withMessages(['personal_code'=>'El código personal es inválido o expiró.']);if($participant->record?->status==='confirmed')throw ValidationException::withMessages(['personal_code'=>'La asistencia de este participante ya fue registrada.']);return$participant;}}
